@props(['name','label','options'=>[],'selected'=>null,'placeholder'=>'Search options...'])
<div data-searchable-select class="form-group position-relative"><label for="{{ $name }}-search">{{ $label }}</label><input type="hidden" name="{{ $name }}" value="{{ old($name,$selected) }}" data-searchable-value><button class="form-control text-left d-flex justify-content-between align-items-center" type="button" data-searchable-toggle aria-expanded="false"><span data-searchable-label>{{ collect($options)->firstWhere('value',old($name,$selected))['label'] ?? 'Select an option' }}</span><i class="fa-solid fa-chevron-down" aria-hidden="true"></i></button><div class="dropdown-menu w-100 p-2" data-searchable-panel hidden><input id="{{ $name }}-search" type="search" class="form-control form-control-sm mb-2" placeholder="{{ $placeholder }}" data-searchable-search><div class="searchable-options" role="listbox">@foreach($options as $option)<button class="dropdown-item" type="button" data-searchable-option data-value="{{ $option['value'] }}" data-label="{{ $option['label'] }}">{{ $option['label'] }}</button>@endforeach</div></div>@error($name)<div class="invalid-feedback d-block">{{ $message }}</div>@enderror</div>
